<!-- pages/report/list.vue — 报告列表，对齐 Reports -->
<template><view class="page-shell"><NavBar title="报告中心"/><view class="body"><view class="filter-row"><view v-for="o in filterOptions" :key="o.value" class="filter-chip" :class="{active:filter===o.value}" @tap="filter=o.value">{{o.label}}</view></view><LoadingSkeleton v-if="loading" /><EmptyState v-else-if="list.length===0" icon="📋" title="暂无诊断报告" desc="上传影像并发起分析后，报告会自动沉淀在这里" /><view v-else class="report-list"><view v-for="r in filteredList" :key="r.id" class="report-card" @tap="goDetail(r.id)"><view class="rc-top"><view><text class="rc-id">报告 #{{r.id}}</text><text class="rc-date">{{fmtDate(r.date||r.createdAt)}}</text></view><view class="rc-conf" :class="confClass(r.confidence)">{{fmtConf(r.confidence)}}</view></view><view class="rc-body"><image v-if="r.imageUrl" :src="r.imageUrl" mode="aspectFill" class="rc-img"/><view class="rc-info"><view class="ri-row"><text class="ri-label">病灶发现</text><text class="ri-val">{{r.findingsCount||0}} 项</text></view><view class="ri-row"><text class="ri-label">状态</text><text class="ri-val">{{r.confidence>=0.8?'重点关注':'常规查看'}}</text></view></view></view><view class="rc-actions"><button class="ra-btn primary" @tap.stop="goDetail(r.id)">查看详情</button></view></view></view></view><TabBar/><AiFab/></view></template>
<script setup>
import {ref,computed,onMounted} from 'vue';import NavBar from '@/components/nav-bar.vue';import TabBar from '@/components/tab-bar.vue';import AiFab from '@/components/ai-fab.vue';import LoadingSkeleton from '@/components/loading-skeleton.vue';import EmptyState from '@/components/empty-state.vue';import {medicalAPI} from '@/api/medical';import {imageUtils} from '@/api/http';import {formatDate} from '@/utils/date'
const list=ref([]);const loading=ref(true);const filter=ref('ALL')
const filterOptions=[{label:'全部',value:'ALL'},{label:'高置信度',value:'HIGH'},{label:'有发现',value:'FINDINGS'}]
const filteredList=computed(()=>list.value.filter(r=>{if(filter.value==='HIGH')return r.confidence>=0.8;if(filter.value==='FINDINGS')return(r.findingsCount||0)>0;return true}))
const fmtDate=(d)=>formatDate(d);const fmtConf=(c)=>c!=null?`${(c*100).toFixed(1)}%`:'--'
const confClass=(c)=>{if(c>=0.8)return'c-high';if(c>=0.6)return'c-mid';return'c-low'}
onMounted(async()=>{try{const r=await medicalAPI.getReports();if(r)list.value=(Array.isArray(r)?r:(r.data||[])).map(item=>({...item,imageUrl:imageUtils.ensureImageUrl(item.imageUrl)}))}catch(e){console.error(e)}finally{loading.value=false}})
const goDetail=(id)=>uni.navigateTo({url:`/subpkg-patient/report/detail?id=${id}`})
</script>
<style scoped>.page-shell{min-height:100vh;background:#040b16}.body{padding:20rpx 28rpx;padding-bottom:160rpx}.filter-row{display:flex;gap:16rpx;margin-bottom:28rpx;flex-wrap:wrap}.filter-chip{padding:14rpx 28rpx;border-radius:999rpx;border:1px solid rgba(125,211,252,0.16);background:rgba(7,21,36,0.68);color:rgba(220,235,255,0.74);font-size:24rpx;font-weight:600}.filter-chip.active{background:linear-gradient(135deg,rgba(24,84,92,0.6),rgba(14,40,70,0.82));border-color:rgba(94,234,212,0.3);color:#f6ffff}.report-list{display:flex;flex-direction:column;gap:20rpx}.report-card{padding:24rpx;border-radius:24rpx;background:linear-gradient(180deg,rgba(7,21,36,0.94),rgba(4,12,24,0.96));border:1px solid rgba(125,211,252,0.12)}.rc-top{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16rpx}.rc-id{font-size:30rpx;font-weight:700;color:#f7fbff}.rc-date{font-size:22rpx;color:rgba(185,214,244,0.66);margin-top:6rpx}.rc-conf{padding:6rpx 20rpx;border-radius:999rpx;font-size:24rpx;font-weight:700}.c-high{background:rgba(248,113,113,0.16);color:#fecaca}.c-mid{background:rgba(250,204,21,0.16);color:#fde68a}.c-low{background:rgba(52,211,153,0.16);color:#bbf7d0}.rc-body{display:flex;gap:16rpx;margin-bottom:16rpx}.rc-img{width:200rpx;height:160rpx;border-radius:16rpx;object-fit:cover}.rc-info{flex:1;display:flex;flex-direction:column;gap:12rpx}.ri-row{display:flex;justify-content:space-between;padding:16rpx;border-radius:14rpx;background:rgba(8,20,35,0.72);border:1px solid rgba(125,211,252,0.08)}.ri-label{font-size:24rpx;color:rgba(220,235,255,0.72)}.ri-val{font-size:24rpx;color:#f7fbff;font-weight:600}.rc-actions{display:flex;justify-content:flex-end}.ra-btn{height:72rpx;padding:0 36rpx;border-radius:999rpx;font-size:24rpx;font-weight:700;border:none}.ra-btn.primary{background:linear-gradient(135deg,#5eead4,#38bdf8);color:#032032}</style>
